parameters.new_string:
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry schema compilation and caching', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws synchronously at register time naming the tool when a static inputSchema is invalid JSON Schema', () => {
    const invalidSchema = {properties: {query: {type: 'unknown-type'}}, type: 'object'};
    const registry = new ToolRegistry();

    expect(() =>
      registry.register({inputSchema: invalidSchema, description: 'Invalid', name: 'bad_schema_tool'}, async () => 'ok')
    ).toThrow('Invalid inputSchema for tool "bad_schema_tool"');
  });

it('rejects input missing a required field with a ToolResponse naming the field and without calling the executor', async () => {
  const executor = jest.fn(async (input: Record<string, unknown>) => String(input.location));
  const locationSchema = {required: ['location'], properties: {location: {type: 'string'}}, type: 'object'};
  const registry = new ToolRegistry();
  registry.register({inputSchema: locationSchema, description: 'Forecast by city', name: 'forecast'}, executor);

  const {result} = await registry.execute('forecast', {});

  expect([executor.mock.calls.length, result]).toEqual([
    0,
    'Invalid input for tool "forecast": location is required',
  ]);
});

it('rejects a wrong-typed property naming the field path and expected type without leaking the offending value to result or logs', async () => {
  const logSpy = jest.fn();
  setLogger({debug: logSpy, info: logSpy, warn: logSpy, error: logSpy});
  const invokedWith: Array<Record<string, unknown>> = [];
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'lookup_patient',
      description: 'Patient lookup',
      inputSchema: {type: 'object', properties: {patientId: {type: 'string'}}},
    },
    async input => {
      invokedWith.push(input);
      return 'ok';
    }
  );

  const response = await registry.execute('lookup_patient', {patientId: 987654321});

  expect({invokedWith, result: response.result, logged: logSpy.mock.calls}).toEqual({
    invokedWith: [],
    result: 'Invalid input for tool "lookup_patient": patientId should be string',
    logged: [['tool', 'invalid input', {name: 'lookup_patient', failures: ['patientId should be string']}]],
  });
});

