it('rejects input missing a required field with a ToolResponse naming the field and without calling the executor', async () => {
  const registry = new ToolRegistry();
  let executorCalls = 0;
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      executorCalls += 1;
      return 'sunny';
    }
  );

  const response = await registry.execute('get_weather', {});

  expect({
    executorCalls,
    namesFieldAsRequired: response.result.includes('location') && /required/i.test(response.result),
  }).toEqual({
    executorCalls: 0,
    namesFieldAsRequired: true,
  });
});

it('rejects a wrong-typed property naming the field path and expected type without leaking the offending value to result or logs', async () => {
  const recordedLogs: string[] = [];
  const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
    recordedLogs.push(JSON.stringify({category, message, fields}));
  };
  const logger: Logger = {
    debug: recordLine,
    info: recordLine,
    warn: recordLine,
    error: recordLine,
  };
  setLogger(logger);

  const registry = new ToolRegistry();
  let executorCalls = 0;
  registry.register(
    {
      name: 'lookup_patient',
      description: 'Look up patient record',
      inputSchema: {
        type: 'object',
        properties: {patientId: {type: 'string'}},
        required: ['patientId'],
      },
    },
    async () => {
      executorCalls += 1;
      return 'ok';
    }
  );

  const response = await registry.execute('lookup_patient', {patientId: 987654321});

  expect({
    executorCalls,
    namesField: response.result.includes('patientId'),
    namesType: response.result.includes('string'),
    leaksValueInResult: response.result.includes('987654321'),
    leaksValueInLogs: recordedLogs.some(line => line.includes('987654321')),
  }).toEqual({
    executorCalls: 0,
    namesField: true,
    namesType: true,
    leaksValueInResult: false,
    leaksValueInLogs: false,
  });
});
